  &reftitle.examples;

   Exemple de Bootstrap


<?php
/**
 * Ce fichier devrait se trouver sous APPLICATION_PATH . "/application/" (qui a
 * été défini dans la configuration passée à Yaf_Application), et être nommé
 * Bootstrap.php, afin que Yaf_Application puisse le trouver.
 */
class Bootstrap extends Yaf_Bootstrap_Abstract {
    public function _initConfig(Yaf_Dispatcher $dispatcher) {
        echo "1er appel\n";
    }

    public function _initPlugin(Yaf_Dispatcher $dispatcher) {
        echo "2e appel\n";
    }
}
?>




   Exemple avec Yaf_Application::bootstrap


<?php
defined('APPLICATION_PATH') // APPLICATION_PATH sera utilisé dans le fichier de configuration ini
    || define('APPLICATION_PATH', __DIR__);

$application = new Yaf_Application(APPLICATION_PATH.'/conf/application.ini');
$application->bootstrap();
?>


   &example.outputs.similar;


1er appel
2e appel
